using MediatR;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using RevenuUsage.Application.Features.ReservesAndObligations;using RevenuUsage.Domain.Entities;namespace RevenuUsage.API.Controllers;
[Authorize][ApiController][Route("api/[controller]")]public sealed class ReservesController:ControllerBase{private readonly IMediator _m;public ReservesController(IMediator m)=>_m=m;[HttpGet]public async Task<ActionResult<IReadOnlyList<ReserveSnapshot>>>Get(DateTime? startDate,DateTime? endDate,CancellationToken ct)=>Ok(await _m.Send(new GetReservesQuery(startDate,endDate),ct));[HttpPost]public async Task<ActionResult>Create(CreateReserveCommand c,CancellationToken ct)=>Ok(new{reserveSnapshotId=await _m.Send(c,ct)});[HttpDelete("{id:guid}")]public async Task<ActionResult>Delete(Guid id,DeleteReserveDto d,CancellationToken ct){await _m.Send(new DeleteReserveCommand(id,d.DeletedBy),ct);return NoContent();}}public sealed record DeleteReserveDto(string DeletedBy);
